'use strict';
const ROLES={BASIC:{name:'Nhân sự chung',sub:'Designer, Editor & vận hành',note:'Học bản sắc, thiết kế và thông tin sản phẩm trung thực cho kênh online.',focus:'Brand DNA · Hình ảnh · Sản phẩm'},CARE:{name:'Customer Care',sub:'Tư vấn & chăm sóc online',note:'Giúp khách hiểu trang sức, kiểm tra thông tin và chọn mua từ xa.',focus:'Sản phẩm · Tư vấn online · Khách hàng'},MKT:{name:'Marketing',sub:'Marketing & content',note:'Truyền thông đúng người, đúng bằng chứng và đúng hành trình mua online.',focus:'Thương hiệu · Khách hàng · Online Journey'}};
const SRC={BRAND:'Thương hiệu COLORA',STORY:'Facets of Feeling',VISUAL:'Nhận diện COLORA',DNA:'Design DNA',GIA:'Kiến thức đá quý',SIZE:'Chọn size online',MATERIAL:'Chất liệu & sản phẩm',WEBSITE:'Website COLORA',SITE:'Website COLORA',AUTH:'Tính xác thực',CUSTOMER:'Khách hàng mục tiêu',GIFT:'Gift Guide',SKU:'Hồ sơ SKU',PRODUCT:'Product Functional / Technical / Emotional',PRICE:'Định hướng giá nội bộ',JOURNEY:'Hành trình online',SEO:'Nội dung & SEO',PRIVACY:'Bảo mật thông tin',WARRANTY:'Bảo hành',SHIPPING:'Giao hàng',RETURNS:'Đổi trả',GIA_CARE:'GIA - Chăm sóc đá & trang sức',COLORA_CARE:'COLORA Care - Tư vấn & hậu mãi',INTERNAL_CASE:'Tình huống mô phỏng tích hợp'};
const state={route:'home',curriculum:null,competencies:null,tasks:[],reviewManifest:null,evidence:null,lessons:[],role:'BASIC',name:'',bank:[],module:null,practice:[],practiceAt:0,practiceAnswers:{},exam:null,attempt:null,examAt:0,reviewFilter:'wrong',filter:'all'};
const statusRisk=s=>/CHỜ|GIẢ THUYẾT|WEB|KIỂM TRA|CHỜ DUYỆT|MÔ PHỎNG|CHÍNH SÁCH WEB|QUY TRÌNH TƯ VẤN|ĐỊNH HƯỚNG|THEO SKU|GIẢ ĐỊNH|INCOME|THỰC TẾ/.test(s);
const ASSESSMENT_VERSION='11.1',CORE_PROGRESS_PREFIX='CORE:';let ASSESSMENT_BANK_ID='unloaded';const KEY='colora-learning-v10-competency-v1',LEGACY_KEY='colora-learning-v9-foundations-roles-assessment-v1';let saveObj={role:'BASIC',name:'',practice:{},teachback:{},performance:{},attempts:[],legacyAttempts:[],exam:null};let tick=null;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrEq=(a,b)=>a.length===b.length && [...a].sort().every((v,i)=>v===[...b].sort()[i]);
const shuffle=a=>{let o=[...a];for(let i=o.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[o[i],o[j]]=[o[j],o[i]]}return o};
function store(){try{localStorage.setItem(KEY,JSON.stringify(saveObj))}catch(e){}}
function recover(){try{const current=localStorage.getItem(KEY);if(current){const r=JSON.parse(current);if(r&&typeof r==='object')saveObj={...saveObj,...r}}else{const old=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');if(old&&typeof old==='object'){saveObj.role=old.role||'BASIC';saveObj.name=old.name||'';saveObj.practice=Object.fromEntries(Object.entries(old.practice||{}).filter(([k])=>!k.includes(':AC-')));saveObj.teachback=old.teachback||{};saveObj.legacyAttempts=(old.attempts||[]).map(a=>({date:a.date,score:a.score,role:a.role,version:'V9'}));store()}}saveObj.practice=saveObj.practice||{};saveObj.teachback=saveObj.teachback||{};saveObj.performance=saveObj.performance||{};saveObj.attempts=Array.isArray(saveObj.attempts)?saveObj.attempts:[]}catch(e){console.warn('Learning record recovery failed',e)}state.role=ROLES[saveObj.role]?saveObj.role:'BASIC';state.name=saveObj.name||'';}
function allRole(){return state.bank.filter(q=>q.role==='CORE'||q.role==='APPLIED'||q.role===state.role)}
function examRole(ex){return ROLES[ex?.role]?ex.role:null}
function examById(ex){const ids=ex?.ids||[];return ids.map(id=>state.bank.find(x=>x.id===id)).filter(Boolean)}
function migrateCoreProgress(){
 const groups=new Map();
 for(const [key,value] of Object.entries(saveObj.practice||{})){
   const match=/^(BASIC|CARE|MKT):(.+)$/.exec(key);
   if(!match||!value||typeof value!=='object')continue;
   const id=match[2],question=state.bank.find(q=>q.id===id);
   if(question?.role!=='CORE')continue;
   const rows=groups.get(id)||[];rows.push(value);groups.set(id,rows);
 }
 for(const [id,rows] of groups){
   const target=CORE_PROGRESS_PREFIX+id;
   if(saveObj.practice[target])rows.push(saveObj.practice[target]);
   rows.sort((a,b)=>(b.at||0)-(a.at||0));
   const latest={...rows[0]};
   const firstKnown=rows.filter(x=>typeof x.firstCorrect==='boolean').sort((a,b)=>(a.at||0)-(b.at||0))[0];
   latest.firstCorrect=firstKnown?.firstCorrect??null;
   latest.attempts=Math.max(...rows.map(x=>x.attempts||1));
   saveObj.practice[target]=latest;
 }
}
function markAssessmentVersion(){
 const previousVersion=saveObj.contentVersion;
 if(previousVersion===ASSESSMENT_VERSION){reconcilePracticeRevisions(previousVersion);return}
 const stale=(saveObj.contentVersion==='10.1'||!saveObj.contentVersion)?Object.entries(saveObj.practice||{}).filter(([key])=>key.includes(':AC-')||key.endsWith(':ON-045')||key.endsWith(':ON-074')):[];
 saveObj.legacyPractice={...(saveObj.legacyPractice||{}),...Object.fromEntries(stale)};
 if(stale.length){const ids=new Set(stale.map(([id])=>id));saveObj.practice=Object.fromEntries(Object.entries(saveObj.practice||{}).filter(([id])=>!ids.has(id)))}
 migrateCoreProgress();
 reconcilePracticeRevisions(previousVersion);
 if(saveObj.exam){saveObj.discardedExamAt=Date.now();saveObj.exam=null}
 saveObj.contentVersion=ASSESSMENT_VERSION;store();
}
function fnv32(text){let h=2166136261;for(let i=0;i<text.length;i++)h=Math.imul(h^text.charCodeAt(i),16777619);return 'fnv1a32-'+(h>>>0).toString(16).padStart(8,'0')}
function questionRevision(q){return fnv32(JSON.stringify([q.id,q.q,q.a,q.key,q.why,q.apply,q.status,q.source,q.role,q.pillar,q.chapter]))}
function reconcilePracticeRevisions(previousVersion){const canMigrate=new Set(['10.1','10.2','11.0']);const old=saveObj.practice||{},revisions=saveObj.legacyPractice||{};for(const [key,row] of Object.entries(old)){const id=/^(?:CORE|BASIC|CARE|MKT):(.+)$/.exec(key)?.[1];const q=id&&state.bank.find(x=>x.id===id),current=q?questionRevision(q):null;if(current&&row&&row.itemRevision===current)continue;if(current&&row&&!row.itemRevision&&canMigrate.has(previousVersion)){row.itemRevision=current;continue}revisions[key+'@'+(row?.itemRevision||'unverified')+'@'+Date.now()]=row;delete old[key]}saveObj.legacyPractice=revisions;saveObj.practice=old}
function assessmentFingerprint(){return fnv32(JSON.stringify({bank:state.bank.map(questionRevision),exam:state.curriculum.exam,essential_ids:state.curriculum.essential_ids,excluded:state.curriculum.assessment_excluded_ids,critical:state.curriculum.critical_ids,matrix:state.competencies,review:state.reviewManifest?.items?.map(x=>[x.id,x.review_status,x.assessment_eligible,x.source_document_id,x.source_version,x.reviewed_at]),evidence:state.evidence?.checks,lessons:state.lessons.map(l=>[l.id,l.title,l.points,l.learning_objective])}))}
function initializeAssessmentBank(){ASSESSMENT_BANK_ID=assessmentFingerprint()}
function assessmentBankId(){return ASSESSMENT_BANK_ID}
function isCurrentAttempt(a){return !!a&&a.assessmentVersion===ASSESSMENT_VERSION&&a.bankId===ASSESSMENT_BANK_ID}
function latestCurrentAttempt(role){return (saveObj.attempts||[]).find(a=>a.role===role&&isCurrentAttempt(a))}
function latestHistoricalAttempt(role){return (saveObj.attempts||[]).find(a=>a.role===role&&!isCurrentAttempt(a))}
function practiceKey(id){const q=state.bank.find(x=>x.id===id);return q?.role==='CORE'?CORE_PROGRESS_PREFIX+id:state.role+':'+id}
const essentialIds=()=>new Set(state.curriculum?.essential_ids||[]);
const essentials=()=>state.bank.filter(q=>q.role==='CORE'&&essentialIds().has(q.id));
const trackLabel=m=>({ESSENTIAL:'BẮT BUỘC',ROLE:'THEO VỊ TRÍ',APPLIED:'TÌNH HUỐNG TÍCH HỢP',ADVANCED:'THƯ VIỆN NÂNG CAO'})[m.role]||m.role;
function labelPillar(p){return ({'THƯƠNG HIỆU':'Thương hiệu','SẢN PHẨM':'Sản phẩm','KHÁCH HÀNG':'Khách hàng','HÀNH TRÌNH':'Customer Journey'})[p]||p}
function answered(id){const q=state.bank.find(x=>x.id===id),row=saveObj.practice[practiceKey(id)];return q&&row?.itemRevision===questionRevision(q)?row:undefined}
function moduleKey(x){if(x.role==='CORE')return (essentialIds().has(x.id)?'ESSENTIAL':'ADVANCED')+'|'+x.chapter;if(x.role==='APPLIED')return 'APPLIED|'+x.pillar;return 'ROLE|'+x.pillar}
function modules(){const map=new Map();for(const q of allRole()){const key=moduleKey(q);const track=key.split('|')[0];if(!map.has(key)){const l=state.lessons.find(z=>z.id===q.chapter);const title=track==='ROLE'?labelPillar(q.pillar):track==='APPLIED'?'Tình huống kết hợp: '+labelPillar(q.pillar):(l?.title||q.topic);map.set(key,{key,role:track,pillar:q.pillar,chapter:q.chapter,title,subtitle:l?.subtitle||'Bài luyện tập ứng dụng',items:[]})}map.get(key).items.push(q)}const order={ESSENTIAL:0,ROLE:1,APPLIED:2,ADVANCED:3};return [...map.values()].sort((a,b)=>(order[a.role]-order[b.role])||(a.chapter||'').localeCompare(b.chapter||'')||a.title.localeCompare(b.title))}
const countDone=qs=>qs.filter(q=>answered(q.id)).length;
const countKnown=qs=>qs.filter(q=>answered(q.id)?.correct).length;
const countFirstCorrect=qs=>qs.filter(q=>answered(q.id)?.firstCorrect===true).length;
const countFirstKnown=qs=>qs.filter(q=>typeof answered(q.id)?.firstCorrect==='boolean').length;
const REVIEW_SEVEN=7*86400000,REVIEW_THIRTY=30*86400000;
function reviewDue(a,now=Date.now()){if(!a?.correct)return false;const stage=a.reviewStage||0;return stage<2&&now-(a.correctAt||a.at)>= (stage===0?REVIEW_SEVEN:REVIEW_THIRTY)}
function practiceUpdate(previous,correct,now=Date.now()){const prev=previous||{},firstCorrect=typeof prev.firstCorrect==='boolean'?prev.firstCorrect:(!previous?correct:null);let reviewStage=prev.reviewStage||0,correctAt=prev.correctAt||now;const eligible=reviewDue(prev,now);if(!correct){reviewStage=0;correctAt=now}else if(eligible){reviewStage=Math.min(2,reviewStage+1);correctAt=now}else if(!previous||!prev.correct){reviewStage=0;correctAt=now}return {correct,at:now,firstCorrect,attempts:(prev.attempts||0)+1,reviewStage,correctAt,reviewedAfterWeek:reviewStage>=1}}

const countNeedReview=qs=>qs.filter(q=>answered(q.id)&&!answered(q.id).correct).length;
const countRecheck=qs=>qs.filter(q=>reviewDue(answered(q.id))).length;
const isReview=q=>!!answered(q.id)&&(!answered(q.id).correct||reviewDue(answered(q.id)));
const progress=qs=>qs.length?Math.round(countDone(qs)/qs.length*100):0;
function nav(r){if(state.exam&&r!=='exam'){if(!confirm('Bạn đang có bài thi chưa nộp. Rời màn hình không hủy bài thi, đồng hồ vẫn chạy. Tiếp tục?'))return}state.route=r;render();scrollTo(0,0)}
function chrome(content){const menus=[['home','⌂','Tổng quan'],['learn','◈','Luyện tập'],['review','↻','Ôn câu sai'],['work','✎','Thực hành'],['exam','▤','Thi tổng kết'],['profile','⚙','Cá nhân']];const roleName=ROLES[state.role].name;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="side-logo">COLORA</div><div class="side-sub">COLOR YOUR AURA</div><div class="side-rule"></div><nav>${menus.map(([id,icon,title])=>`<button class="nav-btn ${state.route===id?'active':''}" data-nav="${id}"><span class="nav-ico">${icon}</span>${title}</button>`).join('')}</nav><div class="side-bottom"><strong>FACETS OF FEELING</strong>Mỗi cảm xúc đều mang một sắc màu.<br>Mỗi giác cắt hé mở một tầng cảm xúc riêng.<br><br>LEARNING STUDIO · COMPETENCY PILOT V11.1</div></aside><div class="main"><div class="mobile-header"><span class="wordmark">COLORA</span><small>LEARNING STUDIO</small></div><header class="topbar"><div class="breadcrumb">INTERNAL LEARNING / ${esc(state.route==='lesson'||state.route==='practice'?'Luyện tập':(menus.find(x=>x[0]===state.route)||menus[0])[2])}</div><div class="avatar"><span>${esc(roleName)}</span><span class="avatar-mark">${esc((state.name||'C').charAt(0).toUpperCase())}</span></div></header><main class="content">${content}<div class="footer-note">COLORA - COLOR YOUR AURA<br>Tiến độ chỉ lưu trên trình duyệt này. Thông số kỹ thuật và chính sách theo SKU cần đối chiếu bản đã duyệt trước khi áp dụng.</div></main></div></div><nav class="mobile-nav">${menus.map(([id,icon,title])=>`<button data-nav="${id}" class="${state.route===id?'active':''}"><b>${icon}</b>${title==='Thực hành'?'Thực hành':title==='Thi tổng kết'?'Bài thi':title==='Tổng quan'?'Trang chủ':title==='Cá nhân'?'Cá nhân':title==='Ôn câu sai'?'Ôn tập':'Luyện tập'}</button>`).join('')}</nav>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav))}
function home(){const qs=essentials(),ms=modules().filter(m=>m.role==='ESSENTIAL'),latest=latestCurrentAttempt(state.role),prior=latestHistoricalAttempt(state.role);chrome(`<section class="hero"><div class="hero-copy"><div class="kicker">COLORA / LEARNING STUDIO</div><h1>Understand the brand.<br>Know the craft.<br>Know your customer.</h1><p>Không chỉ học để trả lời đúng. Học để hiểu sản phẩm, khách hàng và tinh thần COLORA trong từng quyết định.</p><div class="actions"><button class="btn cream" id="go-learn">Bắt đầu luyện tập <span>↗</span></button><button class="btn secondary" style="border-color:#8b9eba;color:#fff" id="go-exam">Thi tổng kết</button></div></div><div class="hero-art" aria-hidden="true"><div class="gem"></div></div></section><div class="grid3"><div class="card"><div class="eyebrow">Lộ trình đang học</div><h3 class="h3" style="margin-top:13px">${esc(ROLES[state.role].name)}</h3><div class="metric-foot">${qs.length} câu Essentials bắt buộc · ${esc(ROLES[state.role].focus)}</div></div><div class="card"><div class="eyebrow">Đã trả lời Essentials</div><div class="metric">${progress(qs)}%</div><div class="metric-foot">${countDone(qs)} đã làm · ${countKnown(qs)} hiện đúng · ${countFirstCorrect(qs)}/${countFirstKnown(qs)} đúng lần đầu (có dữ liệu) · ${countNeedReview(qs)} cần ôn · ${countRecheck(qs)} đến kỳ kiểm tra lại</div><div class="bar" style="margin-top:12px"><span style="width:${progress(qs)}%"></span></div></div><div class="card"><div class="eyebrow">Bài thi V11.1</div><div class="metric">${latest?latest.score+'%':'—'}</div><div class="metric-foot">${latest?`${latest.correct}/${latest.total} câu · ${latest.passed?'Đạt':'Cần ôn thêm'} · V${ASSESSMENT_VERSION}`:prior?'Có bài thi phiên bản cũ; cần thi lại V11.1':'Chưa có lượt thi'}</div></div></div><div class="section-head"><div><div class="kicker">YOUR STUDY PATH</div><h2 class="h2">Học theo chủ đề</h2><p>86 câu Essentials cần học trước. Kiến thức chuyên sâu còn lại không bị xóa mà chuyển thành thư viện theo nhu cầu.</p></div><button class="btn secondary small" id="change-role">Đổi vị trí</button></div><div class="grid2">${ms.map(m=>`<article class="card module"><div class="module-foot"><span class="tag ${m.role==='ESSENTIAL'?'good':''}">${trackLabel(m)}</span><span class="mini-label">${m.items.length} câu</span></div><h3 class="h3">${esc(m.title)}</h3><div class="caption">${m.role==='ESSENTIAL'?'Nền tảng bắt buộc':m.role==='ADVANCED'?'Tham khảo chuyên sâu, không bắt buộc toàn bộ':m.role==='APPLIED'?'Ứng dụng nhiều lớp kiến thức':ROLES[state.role].note}</div><div class="bar"><span style="width:${progress(m.items)}%"></span></div><div class="module-foot"><span class="mini-label">${countDone(m.items)} / ${m.items.length} đã trả lời · ${countKnown(m.items)} hiện đúng</span><button class="faux-link" data-module="${esc(m.key)}">Luyện tập →</button></div></article>`).join('')}</div>`);$('#go-learn').onclick=()=>nav('learn');$('#go-exam').onclick=()=>nav('exam');$('#change-role').onclick=()=>nav('profile');document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>openModule(b.dataset.module));}
function learn(){const ms=modules(),sections=[['ESSENTIAL','01 / COLORA ESSENTIALS','Nền tảng bắt buộc cho mọi vị trí'],['ROLE','02 / MASTERY THEO VỊ TRÍ','Tình huống và kiến thức riêng cho công việc'],['APPLIED','03 / TÌNH HUỐNG TỔNG HỢP','Tập kết nối thương hiệu, sản phẩm và khách hàng'],['ADVANCED','04 / THƯ VIỆN NÂNG CAO','Giữ toàn bộ kiến thức V8.1, chọn học theo công việc']];chrome(`<div class="kicker">PERSONAL LEARNING PATH · V11.1</div><h1 class="h1">Học từ COLORA, không học để đoán đáp án</h1><p class="lead">Bắt đầu với 86 câu Essentials trên 17 chủ đề, sau đó mở sâu theo vai trò. Essentials chỉ hiển thị kiến thức cốt lõi; Advanced mở rộng theo vị trí. Bài tự giải thích là tự nguyện và chưa được chấm.</p>${sections.map(([id,title,sub])=>{const group=ms.filter(m=>m.role===id).sort((a,b)=>id==='ADVANCED'?Number((state.curriculum.role_advanced_chapters[state.role]||[]).includes(b.chapter))-Number((state.curriculum.role_advanced_chapters[state.role]||[]).includes(a.chapter)):0);if(!group.length)return '';return `<details class="track-panel" ${id==='ESSENTIAL'||id==='ROLE'?'open':''}><summary><span><strong>${title}</strong><small>${sub} · ${group.reduce((n,m)=>n+m.items.length,0)} câu</small></span><span aria-hidden="true">⌄</span></summary><div class="grid2">${group.map(m=>`<div class="card module"><div class="eyebrow">${trackLabel(m)} · ${m.items.length} câu${m.role==='ADVANCED'&&(state.curriculum.role_advanced_chapters[state.role]||[]).includes(m.chapter)?' · GỢI Ý CHO VỊ TRÍ':''}</div><h3 class="h3">${esc(m.title)}</h3><div class="mini-label">Đã làm ${countDone(m.items)} · Hiện đúng ${countKnown(m.items)} · Cần ôn ${countNeedReview(m.items)}</div><div class="bar"><span style="width:${progress(m.items)}%"></span></div><button class="btn secondary" data-module="${esc(m.key)}">Bắt đầu / học tiếp →</button></div>`).join('')}</div></details>`}).join('')}`);document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>openModule(b.dataset.module))}
function openModule(key){const mod=modules().find(m=>m.key===key);if(!mod)return;state.module=key;state.practice=mod.items;state.practiceAt=Math.max(0,mod.items.findIndex(q=>!answered(q.id)));if(state.practiceAt<0)state.practiceAt=0;state.practiceAnswers={};state.route=(mod.role==='ESSENTIAL'||mod.role==='ADVANCED')?'lesson':'practice';render();scrollTo(0,0)}
const formatLessonPoint=p=>{const i=p.indexOf(' | ');return i<0?esc(p):`<strong>${esc(p.slice(0,i))}</strong>  ${esc(p.slice(i+3))}`};
